package gen_test

import (
	"go/parser"
	"go/token"
	"strings"
	"testing"

	"github.com/kenshin579/kiwoom-go/tools/gen"
)

func TestRenderSubClient(t *testing.T) {
	g := gen.Group{Menu: "국내주식 > 시세", Market: "domestic", Pkg: "quote",
		Field: "DomesticQuote", Korean: "국내주식 시세"}
	src, err := gen.RenderSubClient(g)
	if err != nil {
		t.Fatalf("RenderSubClient: %v", err)
	}
	got := string(src)
	for _, want := range []string{
		"// Code generated by tools/gen. DO NOT EDIT.",
		"// Package quote 는 키움 국내주식 시세 API 그룹이다.",
		"package quote",
		"type Client struct {",
		"http *transport.Client",
		"func New(hc *transport.Client) *Client",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("%q 가 없다\n---\n%s", want, got)
		}
	}
}

func TestRenderClients(t *testing.T) {
	gs := []gen.Group{
		{Menu: "국내주식 > 시세", Market: "domestic", Pkg: "quote", Field: "DomesticQuote", Korean: "국내주식 시세"},
		{Menu: "미국주식 > 시세", Market: "overseas", Pkg: "quote", Field: "OverseasQuote", Korean: "미국주식 시세"},
	}
	src, err := gen.RenderClients(gs)
	if err != nil {
		t.Fatalf("RenderClients: %v", err)
	}
	got := string(src)
	for _, want := range []string{
		"// Code generated by tools/gen. DO NOT EDIT.",
		"package kiwoom",
		// 패키지명이 같으므로 별칭이 없으면 컴파일되지 않는다
		`domesticquote "github.com/kenshin579/kiwoom-go/domestic/quote"`,
		`overseasquote "github.com/kenshin579/kiwoom-go/overseas/quote"`,
		"type Clients struct {",
		"DomesticQuote *domesticquote.Client",
		"OverseasQuote *overseasquote.Client",
		"func newClients(tr *transport.Client) Clients {",
		"DomesticQuote: domesticquote.New(tr),",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("%q 가 없다\n---\n%s", want, got)
		}
	}
}

func TestRenderClients_빈목록도_컴파일된다(t *testing.T) {
	if _, err := gen.RenderClients(nil); err != nil {
		t.Fatalf("빈 목록: %v", err)
	}
}

// TestRenderSubClient_WebSocket 은 WS 분기(wsSubClientTmpl)를 본다.
//
// 위의 TestRenderSubClient 는 Kind 가 빈 REST 그룹만 쓰므로 이 분기를 한 번도 타지
// 않는다. 특히 Event 봉투가 여기서 다시 정의되지 않는지를 붙잡는다 — 패키지마다
// 복사하면 모양이 같아도 서로 다른 타입이 되어 국내·미국을 한 핸들러로 못 받는다.
func TestRenderSubClient_WebSocket(t *testing.T) {
	for _, g := range []gen.Group{
		{Menu: "국내주식 > 실시간시세", Market: "domestic", Pkg: "realtime",
			Field: "DomesticRealtime", Korean: "국내주식 실시간시세", Kind: gen.KindRealtime},
		{Menu: "미국주식 > 조건검색", Market: "overseas", Pkg: "condition",
			Field: "OverseasCondition", Korean: "미국주식 조건검색", Kind: gen.KindCondition},
	} {
		t.Run(g.Pkg+"_"+string(g.Kind), func(t *testing.T) {
			src, err := gen.RenderSubClient(g)
			if err != nil {
				t.Fatalf("RenderSubClient: %v", err)
			}
			got := string(src)

			if _, err := parser.ParseFile(token.NewFileSet(), "client.go", got, parser.AllErrors); err != nil {
				t.Fatalf("생성물이 Go 로 파싱되지 않는다: %v\n%s", err, got)
			}
			for _, want := range []string{
				"// Code generated by tools/gen. DO NOT EDIT.",
				"package " + g.Pkg,
				"ws *wstransport.Conn",
				"func New(ws *wstransport.Conn) *Client",
				"const defaultBuffer = ",
				`"github.com/kenshin579/kiwoom-go/stream"`,
			} {
				if !strings.Contains(got, want) {
					t.Errorf("%q 가 없다\n---\n%s", want, got)
				}
			}
			// 봉투는 stream 패키지에서 온다. 여기서 다시 정의하면 타입이 갈린다.
			if strings.Contains(got, "type Event") {
				t.Errorf("Event 를 다시 정의한다 — stream.Event 를 써야 한다\n---\n%s", got)
			}
			// REST 전송이 섞여 들어오지 않았는지도 본다.
			if strings.Contains(got, "transport.Client") {
				t.Errorf("WS 그룹인데 REST 전송이 들어 있다\n---\n%s", got)
			}
		})
	}
}
